// ─── Component ───────────────────────────────────────────────────────────────

const PIN_PREFIX = 'pin:';

function isPinEntry(w: WidgetInstance): boolean {
  return w.widgetId.startsWith(PIN_PREFIX);
}

function pinAppId(w: WidgetInstance): string {
  return w.widgetId.slice(PIN_PREFIX.length);
}

interface WidgetGridProps {
  locale: string;
  pinnedAppIds: string[];
  recentAppIds: string[];
  apps: AppDefinition[];
  appMeta: Record<string, { icon: string; label: string; labelPt?: string; description: string; descriptionPt?: string; color: string }>;
  onSelectApp: (app: AppDefinition) => void;
  onTogglePin: (appId: string) => void;
}

const DEVTOOLS_META = { icon: '🛠️', label: 'Dev Tools', color: '#facc15', description: '11 developer tools', descriptionPt: '11 ferramentas de desenvolvimento' };

export function WidgetGrid({ locale, pinnedAppIds, recentAppIds, apps, appMeta, onSelectApp, onTogglePin }: WidgetGridProps) {
  const [items, setItems] = useState<WidgetInstance[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [showPicker, setShowPicker] = useState(false);

  // Load from storage
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const stored = await getSetting(STORAGE_KEY);
      if (cancelled) return;
      if (stored) {
        try { setItems(JSON.parse(stored)); }
        catch { setItems(DEFAULT_WIDGETS); }
      } else {
        setItems(DEFAULT_WIDGETS);
      }
      setLoaded(true);
    })();
    return () => { cancelled = true; };
  }, []);

  // Sync pinnedAppIds into items: add missing pins, remove stale ones
  useEffect(() => {
    if (!loaded) return;
    setItems((prev) => {
      const pinSet = new Set(pinnedAppIds);
      const existingPins = new Set(prev.filter(isPinEntry).map(pinAppId));

      // Remove pins no longer in pinnedAppIds
      let next = prev.filter((w) => !isPinEntry(w) || pinSet.has(pinAppId(w)));

      // Add new pins that don't exist yet
      for (const id of pinnedAppIds) {
        if (!existingPins.has(id)) {
          next = [...next, { id: `pin-${id}`, widgetId: `${PIN_PREFIX}${id}` }];
        }
      }

      if (next.length !== prev.length || next.some((w, i) => w.id !== prev[i]?.id)) {
        putSetting(STORAGE_KEY, JSON.stringify(next));
        return next;
      }
      return prev;
    });
  }, [pinnedAppIds, loaded]);

  // Persist helper
  const persist = useCallback((next: WidgetInstance[]) => {
    setItems(next);
    putSetting(STORAGE_KEY, JSON.stringify(next));
  }, []);

  const addWidget = useCallback((widgetId: string) => {
    const id = `w-${widgetId}-${Date.now()}`;
    persist([...items, { id, widgetId }]);
  }, [items, persist]);

  const removeItem = useCallback((instanceId: string) => {
    const target = items.find((w) => w.id === instanceId);
    if (target && isPinEntry(target)) {
      onTogglePin(pinAppId(target));
      // sync effect will handle removal
      return;
    }
    persist(items.filter((w) => w.id !== instanceId));
  }, [items, persist, onTogglePin]);

  const moveItem = useCallback((instanceId: string, direction: -1 | 1) => {
    const idx = items.findIndex((w) => w.id === instanceId);
    if (idx < 0) return;
    const newIdx = idx + direction;
    if (newIdx < 0 || newIdx >= items.length) return;
    const next = [...items];
    [next[idx], next[newIdx]] = [next[newIdx], next[idx]];
    persist(next);
  }, [items, persist]);

  const activeWidgetIds = useMemo(
    () => new Set(items.filter((w) => !isPinEntry(w)).map((w) => w.widgetId)),
    [items],
  );

  if (!loaded) return null;

  const renderWidget = (instance: WidgetInstance) => {
    switch (instance.widgetId) {
      case 'techscope':
        return <TechScopeLiveWidget />;
      case 'weather':
        return <WeatherWidget locale={locale} />;
      case 'clock':
        return <ClockWidget locale={locale} />;
      case 'quicklinks':
        return (
          <QuickLinksWidget
            locale={locale}
            pinnedAppIds={pinnedAppIds}
            recentAppIds={recentAppIds}
            apps={apps}
            appMeta={appMeta}
            onSelect={onSelectApp}
          />
        );
      case 'news-pt':
        return <NewsPortugalWidget locale={locale} />;
      case 'news-world':
        return <NewsWorldWidget locale={locale} />;
      case 'crypto':
        return <CryptoWidget locale={locale} />;
      case 'seismic':
        return <SeismicWidget locale={locale} />;
      case 'onthisday':
        return <OnThisDayWidget locale={locale} />;
      case 'quotes':
        return <QuotesWidget locale={locale} />;
      case 'analog-clock':
        return <AnalogClockWidget locale={locale} />;
      case 'internet-now':
        return <InternetNowWidget locale={locale} />;
      case 'live-data':
        return <LiveDataWidget locale={locale} />;
      case 'pet':
        return <PetWidget locale={locale} />;
      default:
        return null;
    }
  };

  return (
    <Container>
      <TopRow>
        <SectionTitle>{locale === 'pt' ? 'Dashboard' : 'Dashboard'}</SectionTitle>
        <AddBtn
          active={showPicker}
          onClick={() => setShowPicker(!showPicker)}
        >
          <Plus size={14} />
          {locale === 'pt' ? 'Adicionar widget' : 'Add widget'}
        </AddBtn>
      </TopRow>

      {showPicker && (
        <PickerOverlay>
          <PickerGrid>
            {WIDGET_REGISTRY.map((def) => {
              const added = activeWidgetIds.has(def.id);
              const label = locale === 'pt' ? def.labelPt : def.labelEn;
              const desc = locale === 'pt' ? def.descriptionPt : def.descriptionEn;
              return (
                <PickerItem
                  key={def.id}
                  added={added}
                  onClick={() => { if (!added) { addWidget(def.id); setShowPicker(false); } }}
                >
                  <PickerIcon>{def.icon}</PickerIcon>
                  <PickerInfo>
                    <PickerLabel>{label}{added ? ' ✓' : ''}</PickerLabel>
                    <PickerDesc>{desc}</PickerDesc>
                  </PickerInfo>
                </PickerItem>
              );
            })}
          </PickerGrid>
        </PickerOverlay>
      )}

      {items.length === 0 ? (
        <EmptyDashboard>
          <span>📊</span>
          {locale === 'pt'
            ? 'O teu dashboard está vazio. Adiciona widgets!'
            : 'Your dashboard is empty. Add some widgets!'}
        </EmptyDashboard>
      ) : (
        <Grid>
          {items.map((instance, idx) => {
            // ── Pinned app card ──
            if (isPinEntry(instance)) {
              const appId = pinAppId(instance);
              const isDevtools = appId === 'devtools';
              const meta = isDevtools ? DEVTOOLS_META : appMeta[appId];
              if (!meta) return null;
              const app = isDevtools ? null : apps.find((a) => a.id === appId) ?? null;
              const label = locale === 'pt' && 'labelPt' in meta && meta.labelPt ? meta.labelPt : meta.label;
              const desc = locale === 'pt' && meta.descriptionPt ? meta.descriptionPt : meta.description;
              return (
                <PinnedCard
                  key={instance.id}
                  accentColor={meta.color}
                  onClick={() => {
                    if (app) onSelectApp(app);
                    else window.location.hash = '#/playground';
                  }}
                >
                  <PinnedControls className="pinned-controls">
                    {idx > 0 && (
                      <ControlBtn
                        title={locale === 'pt' ? 'Mover para a esquerda' : 'Move left'}
                        onClick={(e) => { e.stopPropagation(); moveItem(instance.id, -1); }}
                      >
                        <ChevronLeft size={14} />
                      </ControlBtn>
                    )}
                    {idx < items.length - 1 && (
                      <ControlBtn
                        title={locale === 'pt' ? 'Mover para a direita' : 'Move right'}
                        onClick={(e) => { e.stopPropagation(); moveItem(instance.id, 1); }}
                      >
                        <ChevronRight size={14} />
                      </ControlBtn>
                    )}
                    <RemoveBtn
                      title={locale === 'pt' ? 'Desafixar' : 'Unpin'}
                      onClick={(e) => { e.stopPropagation(); removeItem(instance.id); }}
                    >
                      <Pin size={16} />
                    </RemoveBtn>
                  </PinnedControls>
                  <PinnedIconWrap accentColor={meta.color}>{meta.icon}</PinnedIconWrap>
                  <PinnedLabel>{label}</PinnedLabel>
                  <PinnedDesc>{desc}</PinnedDesc>
                  <PinnedFooter accentColor={meta.color}>{locale === 'pt' ? 'Abrir' : 'Open'} &rarr;</PinnedFooter>
                </PinnedCard>
              );
            }

            // ── Widget card ──
            const def = getWidgetDef(instance.widgetId);
            if (!def) return null;
            const accentMap: Record<string, string> = {
              techscope: '#a371f7',
              weather: '#58a6ff',
              clock: '#d29922',
              quicklinks: '#3fb950',
              'news-pt': '#2da44e',
              'news-world': '#cc0000',
              crypto: '#f7931a',
              seismic: '#f97316',
              onthisday: '#d29922',
              quotes: '#a371f7',
              'analog-clock': '#f87171',
              'internet-now': '#e233ff',
              'live-data': '#00d4ff',
              pet: '#e8a0b0',
            };
            return (
              <WidgetCard
                key={instance.id}
                cols={def.defaultCols}
                maxCols={def.maxCols}
                accentColor={accentMap[instance.widgetId]}
              >
                <WidgetControls className="widget-controls">
                  {idx > 0 && (
                    <ControlBtn
                      title={locale === 'pt' ? 'Mover para a esquerda' : 'Move left'}
                      onClick={() => moveItem(instance.id, -1)}
                    >
                      <ChevronLeft size={14} />
                    </ControlBtn>
                  )}
                  {idx < items.length - 1 && (
                    <ControlBtn
                      title={locale === 'pt' ? 'Mover para a direita' : 'Move right'}
                      onClick={() => moveItem(instance.id, 1)}
                    >
                      <ChevronRight size={14} />
                    </ControlBtn>
                  )}
                  <RemoveBtn
                    title={locale === 'pt' ? 'Remover' : 'Remove'}
                    onClick={() => removeItem(instance.id)}
                  >
                    <X size={14} />
                  </RemoveBtn>
                </WidgetControls>
                {renderWidget(instance)}
              </WidgetCard>
            );
          })}
        </Grid>
      )}
    </Container>
  );
}
