import { useState, useEffect, useRef, useCallback } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme, getSetting, putSetting } from '@atlantis/shared';

// ─── Real data channels ─────────────────────────────────────────────────────

const HISTORY_LEN = 24;
const TICK_MS = 5_000;
const PING_CACHE_TTL = 60_000; // 1 minute between real pings per endpoint

interface ChannelDef {
  key: string;
  label: { en: string; pt: string };
  color: string;
  unit: string;
  /** Scale range for the bar/sparkline — values outside are clamped */
  floor: number;
  ceil: number;
}

const CHANNELS: ChannelDef[] = [
  { key: 'github',    label: { en: 'GitHub',     pt: 'GitHub' },     color: '#58a6ff', unit: 'ms', floor: 0, ceil: 500 },
  { key: 'wikipedia', label: { en: 'Wikipedia',  pt: 'Wikipédia' },  color: '#3fb950', unit: 'ms', floor: 0, ceil: 500 },
  { key: 'hn',        label: { en: 'Hacker News',pt: 'Hacker News' },color: '#f97316', unit: 'ms', floor: 0, ceil: 500 },
  { key: 'meteo',     label: { en: 'Open-Meteo', pt: 'Open-Meteo' },color: '#e233ff', unit: 'ms', floor: 0, ceil: 500 },
  { key: 'dom',       label: { en: 'DOM Nodes',  pt: 'Nós DOM' },    color: '#f87171', unit: '',   floor: 0, ceil: 5000 },
  { key: 'fps',       label: { en: 'Frame Rate', pt: 'Frame Rate' }, color: '#d29922', unit: 'fps',floor: 0, ceil: 120 },
];

// Lightweight CORS-enabled endpoints (small payloads)
const PING_ENDPOINTS: Record<string, string> = {
  github:    'https://api.github.com/zen',
  wikipedia: 'https://en.wikipedia.org/w/api.php?action=query&meta=siteinfo&siprop=general&format=json&origin=*',
  hn:        'https://hacker-news.firebaseio.com/v0/maxitem.json',
  meteo:     'https://api.open-meteo.com/v1/forecast?latitude=0&longitude=0&current_weather=true',
};

const PING_KEYS = Object.keys(PING_ENDPOINTS);

interface PingCacheEntry {
  latency: number;
  cachedAt: number;
}

/** Ping with cache — avoids rate limits by reusing recent measurements */
async function cachedPing(key: string, url: string): Promise<number> {
  const cacheKey = `widget-cache:ping-${key}`;
  const raw = await getSetting(cacheKey);
  if (raw) {
    try {
      const entry: PingCacheEntry = JSON.parse(raw);
      if (Date.now() - entry.cachedAt < PING_CACHE_TTL) return entry.latency;
    } catch { /* stale — re-ping */ }
  }

  const t0 = performance.now();
  try {
    await fetch(url);
    const latency = Math.round(performance.now() - t0);
    const entry: PingCacheEntry = { latency, cachedAt: Date.now() };
    putSetting(cacheKey, JSON.stringify(entry));
    return latency;
  } catch {
    return -1;
  }
}

function getDomNodeCount(): number {
  return document.getElementsByTagName('*').length;
}

// ─── FPS tracker ─────────────────────────────────────────────────────────────

function createFpsTracker() {
  let frames = 0;
  let lastTime = performance.now();
  let currentFps = 60;
  let rafId = 0;

  function loop() {
    frames++;
    const now = performance.now();
    const elapsed = now - lastTime;
    if (elapsed >= 1000) {
      currentFps = Math.round((frames * 1000) / elapsed);
      frames = 0;
      lastTime = now;
    }
    rafId = requestAnimationFrame(loop);
  }

  return {
    start() { rafId = requestAnimationFrame(loop); },
    stop() { cancelAnimationFrame(rafId); },
    get fps() { return currentFps; },
  };
}

