// ─── Component ───────────────────────────────────────────────────────────────

interface LiveDataWidgetProps {
  locale: string;
}

export function LiveDataWidget({ locale }: LiveDataWidgetProps) {
  const [histories, setHistories] = useState<number[][]>(() =>
    CHANNELS.map(() => new Array<number>(HISTORY_LEN).fill(0)),
  );
  const [ready, setReady] = useState(false);
  const tickRef = useRef(0);
  const fpsRef = useRef<ReturnType<typeof createFpsTracker> | null>(null);

  // Start FPS tracker
  useEffect(() => {
    const tracker = createFpsTracker();
    fpsRef.current = tracker;
    tracker.start();
    return () => tracker.stop();
  }, []);

  // Tick: rotate through endpoints, always update local metrics
  const tick = useCallback(async () => {
    const currentTick = tickRef.current;
    tickRef.current += 1;

    // Rotate which endpoint to ping (1 per tick, cached to avoid rate limits)
    const pingKey = PING_KEYS[currentTick % PING_KEYS.length];
    const pingUrl = PING_ENDPOINTS[pingKey];
    const latency = await cachedPing(pingKey, pingUrl);

    // Local metrics
    const domCount = getDomNodeCount();
    const fps = fpsRef.current?.fps ?? 0;

    setHistories((prev) =>
      prev.map((hist, ci) => {
        const ch = CHANNELS[ci];
        let value: number;

        if (ch.key === pingKey) {
          value = latency < 0 ? 0 : latency;
        } else if (ch.key === 'dom') {
          value = domCount;
        } else if (ch.key === 'fps') {
          value = fps;
        } else {
          // Not this endpoint's turn — keep last value
          return hist;
        }

        return [...hist.slice(1), value];
      }),
    );

    setReady(true);
  }, []);

  useEffect(() => {
    tick(); // initial
    const id = setInterval(tick, TICK_MS);
    return () => clearInterval(id);
  }, [tick]);

  if (!ready) {
    return (
      <Wrapper>
        <Placeholder>{locale === 'pt' ? 'A medir...' : 'Measuring...'}</Placeholder>
      </Wrapper>
    );
  }

  return (
    <Wrapper>
      <Header>
        <LiveDot />
        {locale === 'pt' ? 'Monitor de Rede' : 'Network Monitor'}
      </Header>
      <ChannelGrid>
        {CHANNELS.map((ch, ci) => {
          const hist = histories[ci];
          const current = hist[hist.length - 1];
          const pct = ((current - ch.floor) / (ch.ceil - ch.floor)) * 100;
          const isLatency = ch.unit === 'ms';
          const warn = isLatency && current > 300;

          const displayValue = ch.key === 'dom' && current >= 1000
            ? `${(current / 1000).toFixed(1)}k`
            : String(Math.round(current));

          return (
            <ChannelRow key={ch.key} delay={ci}>
              <ChannelTop>
                <ChannelLabel>{locale === 'pt' ? ch.label.pt : ch.label.en}</ChannelLabel>
                <ChannelValue color={ch.color} warn={warn}>
                  {displayValue}
                  <ChannelUnit>{ch.unit}</ChannelUnit>
                </ChannelValue>
              </ChannelTop>
              <BarTrack>
                <BarFill pct={pct} color={warn ? '#f85149' : ch.color} />
              </BarTrack>
              <SparkRow>
                {hist.map((v, j) => {
                  const h = Math.max(2, ((v - ch.floor) / (ch.ceil - ch.floor)) * 100);
                  return (
                    <SparkBar
                      key={j}
                      h={Math.min(100, h)}
                      color={warn && j === hist.length - 1 ? '#f85149' : ch.color}
                      latest={j === hist.length - 1}
                    />
                  );
                })}
              </SparkRow>
            </ChannelRow>
          );
        })}
      </ChannelGrid>
    </Wrapper>
  );
}
